### Objective
Build a production-grade High-Velocity Social Feed & Live Interaction Hub demonstrating GetX architecture using GetxController, Rx observables (.obs), Obx surgical rebuilds, debounce search workers, Get.put / Get.find dependency injection, and clean controller lifecycle disposal.

```dart
import 'package:flutter/material.dart';
import 'package:get/get.dart';

void main() {
  // GetMaterialApp activates GetX context-less routing and snackbars
  runApp(const SocialHubApp());
}

/// Root application using GetMaterialApp.
class SocialHubApp extends StatelessWidget {
  const SocialHubApp({super.key});

  @override
  Widget build(BuildContext context) {
    return GetMaterialApp(
      title: 'GetX Social Interaction Hub',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepPurple,
        useMaterial3: true,
      ),
      home: const SocialFeedScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODELS & REACTIVE ENTITIES
// ─────────────────────────────────────────────────────────────────────────────

class PostItem {
  final String id;
  final String author;
  final String avatarInitials;
  final String content;
  final DateTime timestamp;

  // REACTIVE FIELDS: Mutate independently for micro-rebuilds
  final RxInt likes;
  final RxBool isLiked;
  final RxList<String> comments;

  PostItem({
    required this.id,
    required this.author,
    required this.avatarInitials,
    required this.content,
    required this.timestamp,
    int initialLikes = 0,
    bool initialLiked = false,
    List<String>? initialComments,
  })  : likes = initialLikes.obs,
        isLiked = initialLiked.obs,
        comments = (initialComments ?? <String>[]).obs;
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. CONTROLLER LAYER (GetxController with Rx & Workers)
// ─────────────────────────────────────────────────────────────────────────────

class SocialFeedController extends GetxController {
  // Observable collections and primitives
  final RxList<PostItem> _posts = <PostItem>[].obs;
  final RxString searchQuery = ''.obs;
  final RxString activeFilterTag = 'All'.obs;
  final RxBool isRefreshing = false.obs;

  // Computed getter: filters posts dynamically based on search & filter tag
  List<PostItem> get filteredPosts {
    final query = searchQuery.value.trim().toLowerCase();
    return _posts.where((post) {
      final matchesQuery = query.isEmpty ||
          post.author.toLowerCase().contains(query) ||
          post.content.toLowerCase().contains(query);
      return matchesQuery;
    }).toList();
  }

  int get totalLikesReceived =>
      _posts.fold(0, (sum, post) => sum + post.likes.value);

  @override
  void onInit() {
    super.onInit();
    _seedInitialPosts();

    // WORKER: Debounce search input to prevent rapid recalculations
    debounce<String>(
      searchQuery,
      (query) {
        // Logs or analytics dispatch on debounced search
        debugPrint('Debounced search query: $query');
      },
      time: const Duration(milliseconds: 300),
    );
  }

  @override
  void onReady() {
    super.onReady();
    // Triggered 1 frame after render: safe for snackbars or network calls
    Get.snackbar(
      'Welcome Back!',
      'Feed synchronized successfully with local cache.',
      snackPosition: SnackPosition.BOTTOM,
      duration: const Duration(seconds: 2),
      margin: const EdgeInsets.all(12),
      backgroundColor: Colors.deepPurple.shade50,
    );
  }

  void _seedInitialPosts() {
    _posts.assignAll([
      PostItem(
        id: 'post_1',
        author: 'Arpit Aswal',
        avatarInitials: 'AA',
        content:
            'Testing GetX micro-reactivity: notice how tapping the heart updates only this card\'s like count without rebuilding the list!',
        timestamp: DateTime.now().subtract(const Duration(minutes: 15)),
        initialLikes: 14,
        initialLiked: true,
        initialComments: ['Impressive performance!', 'Clean syntax.'],
      ),
      PostItem(
        id: 'post_2',
        author: 'Flutter Core Team',
        avatarInitials: 'FC',
        content:
            'Modern declarative state architectures allow granular rebuild isolation and predictable app performance.',
        timestamp: DateTime.now().subtract(const Duration(hours: 1)),
        initialLikes: 42,
        initialLiked: false,
        initialComments: ['Agreed!'],
      ),
      PostItem(
        id: 'post_3',
        author: 'Mobile Architect',
        avatarInitials: 'MA',
        content:
            'Choose your tools wisely: Riverpod for compile-time safety and enterprise scale; GetX for rapid prototyping and low ceremony.',
        timestamp: DateTime.now().subtract(const Duration(hours: 3)),
        initialLikes: 88,
        initialLiked: false,
      ),
    ]);
  }

  void toggleLike(PostItem post) {
    if (post.isLiked.value) {
      post.likes.value--;
      post.isLiked.value = false;
    } else {
      post.likes.value++;
      post.isLiked.value = true;
    }
  }

  void addComment(PostItem post, String comment) {
    if (comment.trim().isEmpty) return;
    post.comments.add(comment.trim());
  }

  void createPost(String content) {
    if (content.trim().isEmpty) return;
    _posts.insert(
      0,
      PostItem(
        id: 'post_${DateTime.now().millisecondsSinceEpoch}',
        author: 'Current User',
        avatarInitials: 'CU',
        content: content.trim(),
        timestamp: DateTime.now(),
      ),
    );
  }

  Future<void> simulateNetworkRefresh() async {
    isRefreshing.value = true;
    await Future.delayed(const Duration(milliseconds: 1200));
    _seedInitialPosts();
    isRefreshing.value = false;
  }

  @override
  void onClose() {
    // Cleanup workers, streams, or text controllers here
    super.onClose();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRESENTATION LAYER (Screens & Fine-Grained Obx Leaves)
// ─────────────────────────────────────────────────────────────────────────────

class SocialFeedScreen extends StatelessWidget {
  const SocialFeedScreen({super.key});

  void _showNewPostSheet(BuildContext context, SocialFeedController controller) {
    final textController = TextEditingController();

    Get.bottomSheet(
      Container(
        padding: const EdgeInsets.all(20),
        decoration: const BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            const Text('Publish New Thought', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
            const SizedBox(height: 12),
            TextField(
              controller: textController,
              maxLines: 3,
              autofocus: true,
              decoration: const InputDecoration(
                hintText: 'What is on your mind regarding Flutter architecture?',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 16),
            FilledButton(
              onPressed: () {
                controller.createPost(textController.text);
                Get.back(); // Context-less pop
                Get.snackbar('Published', 'Your post is now live on the feed!', snackPosition: SnackPosition.BOTTOM);
              },
              child: const Text('Post to Feed'),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    // 1. SERVICE LOCATOR REGISTRATION: Inject controller eagerly
    final controller = Get.put(SocialFeedController());

    return Scaffold(
      appBar: AppBar(
        title: const Text('Social Pulse'),
        actions: [
          // SURGICAL REBUILD: Only this metric badge rebuilds when any post is liked!
          Obx(() => Container(
                margin: const EdgeInsets.only(right: 16),
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  color: Theme.of(context).colorScheme.primaryContainer,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Row(
                  children: [
                    const Icon(Icons.favorite, size: 16, color: Colors.redAccent),
                    const SizedBox(width: 6),
                    Text(
                      '${controller.totalLikesReceived}',
                      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
                    ),
                  ],
                ),
              )),
        ],
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(60),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            child: SearchBar(
              hintText: 'Search feed or author...',
              leading: const Icon(Icons.search),
              onChanged: (val) => controller.searchQuery.value = val,
            ),
          ),
        ),
      ),
      body: Obx(() {
        final posts = controller.filteredPosts;

        if (controller.isRefreshing.value) {
          return const Center(child: CircularProgressIndicator());
        }

        if (posts.isEmpty) {
          return const Center(child: Text('No posts found.'));
        }

        return RefreshIndicator(
          onRefresh: controller.simulateNetworkRefresh,
          child: ListView.separated(
            padding: const EdgeInsets.all(16),
            itemCount: posts.length,
            separatorBuilder: (_, __) => const SizedBox(height: 12),
            itemBuilder: (context, index) {
              final post = posts[index];
              return _PostCard(post: post, controller: controller);
            },
          ),
        );
      }),
      floatingActionButton: FloatingActionButton(
        onPressed: () => _showNewPostSheet(context, controller),
        tooltip: 'New Post',
        child: const Icon(Icons.add_comment_outlined),
      ),
    );
  }
}

/// Individual Post Card with Surgical Obx Listeners
class _PostCard extends StatelessWidget {
  final PostItem post;
  final SocialFeedController controller;

  const _PostCard({required this.post, required this.controller});

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                CircleAvatar(
                  backgroundColor: Colors.deepPurple.shade100,
                  child: Text(post.avatarInitials, style: const TextStyle(fontWeight: FontWeight.bold, color: Colors.deepPurple)),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(post.author, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
                      Text(
                        '${DateTime.now().difference(post.timestamp).inMinutes}m ago',
                        style: const TextStyle(fontSize: 11, color: Colors.grey),
                      ),
                    ],
                  ),
                ),
              ],
            ),
            const SizedBox(height: 12),
            Text(post.content, style: const TextStyle(fontSize: 14, height: 1.4)),
            const Divider(height: 24),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                // SURGICAL REBUILD: Only this specific like button rebuilds on tap!
                Obx(() => TextButton.icon(
                      onPressed: () => controller.toggleLike(post),
                      icon: Icon(
                        post.isLiked.value ? Icons.favorite : Icons.favorite_border,
                        color: post.isLiked.value ? Colors.red : Colors.grey,
                        size: 20,
                      ),
                      label: Text(
                        '${post.likes.value}',
                        style: TextStyle(
                          color: post.isLiked.value ? Colors.red : Colors.grey,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    )),
                // SURGICAL REBUILD: Comments count
                Obx(() => TextButton.icon(
                      onPressed: () {
                        controller.addComment(post, 'Quick praise from live UI!');
                      },
                      icon: const Icon(Icons.mode_comment_outlined, size: 20, color: Colors.grey),
                      label: Text('${post.comments.length}', style: const TextStyle(color: Colors.grey)),
                    )),
                IconButton(
                  icon: const Icon(Icons.share_outlined, size: 20, color: Colors.grey),
                  onPressed: () {
                    Get.snackbar('Share Link', 'Copied direct link for ${post.id}', snackPosition: SnackPosition.BOTTOM);
                  },
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Service Locator Injection via Get.put**:
   Inside `SocialFeedScreen.build`, `Get.put(SocialFeedController())` registers the singleton controller into GetX's global in-memory hash map. Any descendant or distant widget can locate this instance without `BuildContext` via `Get.find<SocialFeedController>()`.
2. **Micro-Reactivity via .obs on Granular Fields**:
   In `PostItem`, rather than making the entire class a stream, we made individual fields reactive: `likes = initialLikes.obs` and `isLiked = initialLiked.obs`. In `_PostCard`, `Obx` wraps strictly the like `TextButton`. When the user taps 'Like', **only this tiny button element rebuilds**! The rest of the card, the author avatar, the text content, and the surrounding list view remain completely untouched.
3. **Automatic Dependency Tracking in Obx**:
   `Obx` requires zero explicit parameter binding. During its build phase, GetX's internal observer records that `post.likes.value` and `post.isLiked.value` were accessed. When either property mutates, GetX schedules a rebuild strictly for that `Obx` element.
4. **Reactive Workers with Debounce**:
   Inside `SocialFeedController.onInit()`, the `debounce(searchQuery, ...)` worker listens to the search query `RxString`. If the user types rapidly, it waits for 300ms of inactivity before firing the search callback, preventing search calculation thrashing.
5. **Context-Less UI Feedback**:
   In `onReady()` and button callbacks, `Get.snackbar()` and `Get.bottomSheet()` display overlays without needing a `BuildContext` argument.
